function MovieDetails({ movie }) {
  return (
    <div className="details">
      <header>
        <h2>{movie.title}</h2>
        <p>Year: {movie.year}</p>
        <img src={movie.poster} alt={movie.title} />
      </header>
    </div>
  );
}

export default MovieDetails;
